module asyn_fifo( 
//Inputs
	wclk, rclk, wrstn, rrstn, winc, rinc, wdata,	
//Outputs		
	wfull, rempty, rdata 	
//Parameters
);
	parameter WIDTH = 8;
	parameter DEPTH = 16;
//Port Declaration	
	input wclk;			
	input rclk;			
	input wrstn;		
	input rrstn;		
	input winc;		
	input rinc;		
	input [WIDTH-1:0] wdata;	

	output wfull; 		
	output rempty;	
	output [WIDTH-1:0] rdata;	
	integer i,j,k;
	reg [(DEPTH*WIDTH)-1:0]RAM;
	reg [$clog2(DEPTH):0]wptr,rptr,wptr_buff,rptr_buff;
	wire [$clog2(DEPTH):0]wptr_syn,rptr_syn;
	wire wen,ren;
	reg [WIDTH-1:0]rdata_ram;
	wire [$clog2(DEPTH):0]waddr,raddr;
	wire [WIDTH-1:0]wdata_ram;
	wire [$clog2(DEPTH):0]waddr_bin,raddr_bin;

	always@(posedge wclk,negedge wrstn)
	begin
		if(!wrstn)
			wptr<=0;
		else
			wptr<=(winc&&!wfull)?(wptr+1):(wptr);
	end

	always@(posedge rclk,negedge rrstn)
	begin
		if(!rrstn)
			rptr<=0;
		else
			rptr<=(rinc&&!rempty)?(rptr+1):(rptr);
	end

	always@(posedge wclk,negedge wrstn)
	begin
		if(!wrstn)
			RAM<=0;
		else if(wen)
			RAM[waddr]=wdata_ram;
	end

	always@(posedge rclk,negedge rrstn)
	begin
		if(!rrstn)
			rdata_ram<=0;
		else if(ren)
			rdata_ram<=RAM[raddr];
	end

	always@(posedge wclk,negedge wrstn)
	begin
		if(!wrstn)
			wptr_buff<=0;
		else
			wptr_buff<=wptr;
	end

	always@(posedge rclk,negedge rrstn)
	begin
		if(!rrstn)
			rptr_buff<=0;
		else
			rptr_buff<=rptr;
	end

	assign wen=winc&&(!wfull);
	assign ren=rinc&&(!rempty);
	assign waddr_bin=wptr^((wptr>>1));
	assign raddr_bin=rptr^((rptr>>1)); 

	assign waddr=$unsigned(waddr_bin);
	assign raddr=$unsigned(raddr_bin);
	assign wdata_ram=wdata;
	assign rdata=rdata_ram;

	assign wfull=(wptr=={~rptr_syn[$clog2(DEPTH):$clog2(DEPTH)-1],rptr_syn[$clog2(DEPTH)-2:0]});
	assign rempty=(rptr==wptr_syn);

	assign wptr_syn={1'b0,wptr_buff}>>(1)+{1'b0,wptr_buff};
	assign rptr_syn={1'b0,rptr_buff}>>(1)+{1'b0,rptr_buff};

endmodule
